class CreateJobDialog{constructor($scope,$mdDialog,DispatchData,toastrService,loadingService,$http,$httpParamSerializer){this.$scope=$scope;this.$mdDialog=$mdDialog;this.DispatchData=DispatchData;this.$http=$http;this.$httpParamSerializer=$httpParamSerializer;this.toastrService=toastrService;this.loadingService=loadingService;this.jobForm=$scope.jobForm;this.fromAddressSearchText="";this.toAddressSearchText="";this.searchClientText="";this.selectedClient=null;this.selectedFromAddress=null;this.selectedToAddress=null;this.job={clientID:"",deliverToContact:"",fromAddress:"",toAddress:"",date:new Date,fromContactName:"",deliveryNotes:"",pickupNotes:"",van:false,truck:false,pedal:false,attention:false,vanOK:false,reprice:false,void:false,done:false,charge:0}}async clientSearchAutocomplete(searchTerm){const url="/home/ActiveClients";try{return await this.DispatchData.autocompleteSearch(searchTerm,url)}catch(error){this.toastrService.showErrorToast(error.message)}}async addressSearchAutocomplete(searchText){try{const suggestions=await this.DispatchData.autocompleteAddressSearch(searchText);return this.transformSuggestions(suggestions)}catch(error){this.toastrService.showErrorToast(error.message)}}transformSuggestions(data){return data.suggestions.map(obj=>({id:obj.locationId,text:obj.label.split(", ").reverse().join(", ")}))}async submit(job){try{if(!this.jobForm.$valid){this.toastrService.showWarningToast("Please complete all the fields");return}job.clientID=this.selectedClient.id;job.fromAddress=this.selectedFromAddress.text;job.toAddress=this.selectedToAddress.text;const response=await this.createJob(job);const newJobId=response.data;this.toastrService.showSuccessToast("New Job Created Successfully");this.$mdDialog.hide(newJobId)}catch(error){this.toastrService.showErrorToast(error.message)}}async createJob(job){try{const url="job/createJob";return await this.$http({url:url,method:"POST",data:job,headers:{"Content-Type":"application/json"}})}catch(error){this.toastrService.showErrorToast(error.message)}}cancel(){this.$mdDialog.cancel()}}